INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_28_m_28_1_36',
  'Which AWS SDK feature helps prevent a single failing service from being overwhelmed by repeated, immediate retry attempts from a client application?',
  'mcq',
  '["Exponential backoff with jitter","Client-side caching","Asynchronous invocation","Batch processing"]'::json,
  '{0}',
  'Option A (correct) refers to exponential backoff with jitter, a crucial AWS SDK feature and best practice for error handling. It involves increasing the wait time between retries exponentially and adding a small random delay (jitter) to prevent all clients from retrying simultaneously, which can overwhelm a struggling service. Option B (Client-side caching) is a performance optimization for data retrieval, not for managing retry logic. Option C (Asynchronous invocation) is a way to call services without waiting for a response, but it doesn''t directly manage retry attempts for failed calls. Option D (Batch processing) is a method for processing multiple items together, which is unrelated to individual retry mechanisms.',
  NOW(),
  'quiz_domain28_6',
  NOW(),
  1,
  NULL,
  NULL,
  'm_28_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
