INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_28_m_28_1_45',
  'Which AWS service is a fully managed Kubernetes service that allows you to run Kubernetes on AWS without needing to install, operate, and maintain your own Kubernetes control plane?',
  'mcq',
  '["Amazon EC2","Amazon ECS","AWS App Runner","Amazon EKS"]'::json,
