INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_3_38',
  'A developer wants to test an AWS Lambda function locally on their machine without deploying it to the AWS cloud or incurring any costs. Which AWS tool is specifically designed for this purpose?',
