INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_3_42',
  'A development team wants to ensure that their serverless application''s integration tests are run automatically whenever new code is pushed to the repository. Which AWS service should be used to automate the execution of these tests as part of a CI/CD pipeline?',
  'mcq',
