INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_3_50',
  'A development team is frequently testing new AWS Lambda function versions directly against their production Amazon DynamoDB tables. This practice has led to occasional data corruption and unexpected costs. Which approach should the team adopt to prevent these issues while maintaining development velocity?',
