);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_1_29',
  'A developer is preparing a Docker container image for a microservice that will run on Amazon ECS. Which AWS service should be used to store and manage this container image?',
  'mcq',
