INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_28_m_28_2_103',
  'A developer wants to quickly expose an AWS Lambda function via a dedicated HTTP endpoint without using Amazon API Gateway. Order the steps to enable and configure a Lambda Function URL.',
