INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_3_64',
  'Which configuration files are commonly used to define deployment behavior for AWS CodeDeploy and build specifications for AWS CodeBuild? (Select TWO.)',
  'multiple',
  '["AppSpec file","buildspec.yml","template.yaml","Dockerfile","serverless.yml"]'::json,
  '{0,1}',
  'Option A (AppSpec file) is used by AWS CodeDeploy to manage the deployment lifecycle, specifying actions to be performed on instances. Option B (buildspec.yml) is used by AWS CodeBuild to define the commands and settings for the build process. Option C (template.yaml) is for AWS SAM. Option D (Dockerfile) is for Docker container images. Option E (serverless.yml) is for the Serverless Framework, not a native AWS service configuration file.',
  NOW(),
  'quiz_domain30_6',
