INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_4_58',
  'Which AWS services are fundamental for setting up a complete CI/CD pipeline on AWS? (Select THREE.)',
  'multiple',
  '["AWS CodeCommit","AWS CodeBuild","AWS CodePipeline","Amazon SQS","AWS Lambda"]'::json,
  '{0,1,2}',
  'Option A (AWS CodeCommit) provides source control. Option B (AWS CodeBuild) compiles source code and runs tests. Option C (AWS CodePipeline) orchestrates the entire workflow, integrating with CodeCommit for source, CodeBuild for build, and CodeDeploy for deployment. Together, these three form the core of an AWS CI/CD pipeline. Option D (Amazon SQS) is a message queuing service. Option E (AWS Lambda) is a serverless compute service.',
  NOW(),
  'quiz_domain30_6',
  NOW(),
  25,
  NULL,
  NULL,
  'm_30_4',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
