INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_4_60',
  'Which AWS services can be used to manage environment variables and sensitive configuration data within CI/CD pipelines? (Select TWO.)',
