INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_1_49',
  'When preparing AWS Lambda function deployment packages, which components can be included to extend functionality or manage dependencies? (Select TWO.)',
