INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_2_56',
  'Which AWS services allow developers to define and deploy application stacks to staging environments for functional testing? (Select TWO.)',
