INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_30_m_30_2_57',
  'Which AWS services are used for local development and debugging of serverless applications without deploying to the cloud? (Select TWO.)',
