INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_29_m_29_2_97',
  'A developer needs to store sensitive application configuration in a secure manner and ensure it''s encrypted at rest. Order the steps to achieve this using AWS KMS and an application.',
  'ordering',
